import{_ as i,o as n,c as o,a2 as t}from"./chunks/framework.CxN14L7e.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),l={name:"changelog.md"};function a(s,e,r,d,g,c){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="v1-0-0-—-july-2026" tabindex="-1">v1.0.0 — July 2026 <a class="header-anchor" href="#v1-0-0-—-july-2026" aria-label="Permalink to &quot;v1.0.0 — July 2026&quot;">​</a></h2><h3 id="initial-release" tabindex="-1">Initial Release <a class="header-anchor" href="#initial-release" aria-label="Permalink to &quot;Initial Release&quot;">​</a></h3><p>First public release of the eFinSign API.</p><p><strong>Features:</strong></p><ul><li><strong>Documents API</strong> — Upload, manage, and send PDFs for signing (10 endpoints)</li><li><strong>Signers &amp; Fields API</strong> — Add signers with signature fields (7 endpoints)</li><li><strong>Templates API</strong> — Create reusable templates and instantiate documents (5 endpoints)</li><li><strong>Embed API</strong> — Generate embeddable signing URLs (2 endpoints)</li><li><strong>Webhooks API</strong> — Register and manage webhook endpoints (4 endpoints)</li><li><strong>Organization API</strong> — Read and update org profile, view usage (3 endpoints)</li><li><strong>Clients API</strong> — Address book CRUD (5 endpoints)</li></ul><p><strong>Authentication:</strong></p><ul><li>Bearer token API keys (<code>efsk_test_</code> / <code>efsk_live_</code>)</li><li>Scope-based access control (8 scopes)</li><li>Sandbox mode with instant key generation</li><li>Production mode tied to subscription plans</li></ul><p><strong>Webhooks:</strong></p><ul><li>Event-driven with HMAC-SHA256 signatures</li><li>4 event types: <code>document.sent</code>, <code>document.completed</code>, <code>document.voided</code>, <code>document.signer_signed</code>, <code>document.signer_declined</code></li><li>Database triggers for reliable event queuing</li><li>Retry logic with failure counting</li></ul><p><strong>Developer Experience:</strong></p><ul><li>OpenAPI 3.1 specification (<code>/openapi.json</code>)</li><li>Developer portal at <code>efinsign.ca/developers</code></li><li>Interactive API explorer via Scalar</li><li>cURL examples for all endpoints</li></ul><p><strong>Pending (v1.1+):</strong></p><ul><li><code>@efinsign/api</code> npm package (SDK)</li><li>Embeddable signing widget (iframe + PostMessage)</li><li>Postman Collection</li><li>Rate limiting analytics dashboard</li><li>Additional webhook event types</li></ul>',14)])])}const h=i(l,[["render",a]]);export{u as __pageData,h as default};
